nodes.css:
.sheet { position: absolute; left: 180px; width: 1560px; top: 300px;
  display: flex; flex-direction: column; gap: 24px; padding: 44px 48px 48px 48px;
  border-radius: 16px; background: rgba(12,13,16,0.92);
  border: 1px solid rgba(244,241,234,0.10); border-left: 4px solid #d9a441;
  box-shadow: 0 12px 32px rgba(0,0,0,0.35); }
.q { font-family: Archivo, Inter, DejaVu Sans; font-size: 66px; font-weight: 700; line-height: 1.14;
  letter-spacing: -0.02em; color: #f4f1ea; }
.a { font-family: JetBrains Mono, DejaVu Sans Mono, monospace; font-size: 18px; letter-spacing: 0.22em; color: #9a978e; }
.marks { font-family: Archivo, Inter, DejaVu Sans; font-size: 96px; font-weight: 900; color: #d9a441; line-height: 1; }
